INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Horns around a lunar disk' WHERE source_id='dd-3.0' AND slug='nephthys' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Crook and flail' WHERE source_id='dd-3.0' AND slug='osiris' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Bull' WHERE source_id='dd-3.0' AND slug='ptah' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Coiled cobra' WHERE source_id='dd-3.0' AND slug='set' AND owner_user_id IS NULL;

WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-nephthys','Nephthys Divine Stat Block','149-151',
 'Nephthys, Protector of the Dead, is the divine-rank-12 intermediate Pharaonic deity of death and grief.',
 '{"deitySlug":"nephthys","pantheon":"pharaonic","sourceEdition":"3.0","rankBand":"intermediate","divineRank":12,"titles":["Protector of the Dead"],"symbol":"Horns around a lunar disk","homePlane":"The Offering Fields","alignment":"CG","classes":[{"class":"Cleric","level":20},{"class":"Necromancer","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+160 outsider + 20d8+160 cleric + 20d4+160 necromancer","hitPoints":880,"initiative":8,"speed":{"land":60,"fly":100,"maneuverability":"perfect"},"armorClass":{"total":64,"dexterity":8,"divine":12,"natural":25,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"heavyMace":"+65/+60/+55/+50 melee, +5 disruption holy heavy mace","heavyMaceDamage":"1d8+17/x2","spellTouch":{"melee":60,"ranged":60}},"saves":{"fort":52,"ref":52,"will":61,"intermediateDeityChecksAlways20":true},"abilities":{"str":27,"dex":27,"con":27,"int":33,"wis":44,"cha":29},"specialAttacks":{"turnUndeadPerDay":20},"specialQualities":{"printedDamageReduction":"47/+4","printedFireResistance":32,"spellResistance":64,"divineAura":{"radiusFeet":1200,"dc":31},"familiar":"vultures","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Reality","Arcane Mastery","Area Divine Shield","Automatic Metamagic (maximize wizard spells)","Automatic Metamagic (quicken wizard spells)","Control Creatures (undead)","Divine Inspiration (despair)","Divine Shield","Divine Spellcasting","Extra Domain (Repose)","Hand of Death","Increased Spell Resistance","Know Death","Life and Death","Spontaneous Wizard Spells"],"domainPowers":{"chaosSpellsCasterLevelBonus":1,"goodSpellsCasterLevelBonus":1,"protectiveWardUsesPerDay":12,"protectiveWardResistanceBonus":20,"deathTouchUsesPerDay":12,"deathTouchDice":"20d6"},"spellLikeAbilities":{"casterLevel":22,"chaosAndGoodCasterLevel":23,"saveDc":"31 + spell level"},"spellcasting":{"clericSpellsPerDayLevels0To17":"6/11/10/10/10/10/8/8/8/8/3/3/3/3/2/2/2/2","clericBaseDc":"29 + spell level; 33 + spell level for necromancy","wizardSpellsPerDayLevels0To11":"5/8/8/8/7/7/7/7/6/6/2/2","wizardBaseDc":"23 + spell level; 27 + spell level for necromancy","prohibitedSchool":"Illusion"},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["chaotic","good"],"damageReduction":"25/epic","fireResistance":17,"additionalOutsiderSkillPoints":true,"wizardSpecialization":"Apply revised school-specialization rules.","divineInspirationDespair":"Use the revised crushing-despair-style -4 penalty where applicable.","defunctSkills":["Scry ranks reassigned"]}}'),

('dd-statblock-osiris','Osiris Divine Stat Block','151-153',
 'Osiris is the divine-rank-18 greater Pharaonic deity of harvest, nature, the underworld, and judgment of the dead.',
 '{"deitySlug":"osiris","pantheon":"pharaonic","sourceEdition":"3.0","rankBand":"greater","divineRank":18,"symbol":"Crook and flail","homePlane":"The Offering Fields","alignment":"LG","classes":[{"class":"Cleric","level":18},{"class":"Monk","level":12},{"class":"Ranger","level":10}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+360 outsider + 18d8+324 cleric + 12d8+216 monk + 10d10+180 ranger","hitPoints":1580,"initiative":9,"speed":{"land":140},"armorClass":{"total":89,"dexterity":9,"monk":12,"divine":18,"natural":31,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"heavyFlail":"+75/+70/+65/+60 melee, +5 disruption defending heavy flail","heavyFlailDamage":"1d10+21/17-20/x2; greater deity maximum 31","spellTouch":{"melee":69,"ranged":67},"greaterDeityAlways20OnAttacks":true,"greaterDeityMaximumDamage":true},"saves":{"fort":68,"ref":59,"will":60,"greaterDeityAlways20":true},"abilities":{"str":33,"dex":28,"con":46,"int":28,"wis":30,"cha":29},"specialAttacks":{"turnUndeadPerDay":16,"stunningAttack":{"usesPerDay":12,"dc":26},"kiStrike":"+1","flurryOfBlows":true},"specialQualities":{"printedDamageReduction":"71/+5","sourceDamageReductionNote":"The individual 3.0 stat block explicitly prints DR 71/+5. This unusually high value is retained verbatim and is not silently normalized.","printedFireResistance":38,"fastHealing":38,"spellResistance":50,"divineAura":{"radiusMiles":18,"dc":37},"monkFeatures":["evasion","still mind +2 vs enchantment","slow fall 50 ft.","purity of body","wholeness of body 24 hp","leap of the clouds","improved evasion","diamond body","abundant step"],"favoredEnemies":"undead +3, demons +2, aberrations +1","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Annihilating Strike","Command Plants","Divine Blast","Divine Blessing (Constitution)","Divine Fast Healing","Energy Storm (positive energy)","Extra Domain (Air)","Extra Domain (Earth)","Extra Domain (Repose)","Hand of Death","Increased Damage Reduction","Life and Death (no rest required)","Mass Divine Blast","Mass Life and Death","Power of Nature","Rejuvenation","Shapechange","Speak with Creatures (plants)","Undead Mastery","Undead Qualities"],"domainPowers":{"airTurningUsesPerDay":18,"earthTurningUsesPerDay":18,"goodSpellsCasterLevelBonus":1,"lawSpellsCasterLevelBonus":1,"plantRebukeCommandUsesPerDay":18,"deathTouchUsesPerDay":18,"deathTouchThresholdHp":108},"spellLikeAbilities":{"casterLevel":28,"goodAndLawCasterLevel":29,"saveDc":"37 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/9/9/8/8/7/7/5/5/4","clericBaseDc":"20 + spell level","rangerSpellsPerDay":"4/4","rangerBaseDc":"20 + spell level"},"possessions":{"crown":"Grants true-seeing-style perception of invisible creatures/objects and illusions; negates spells of 4th level or lower that target Osiris; immediately kills a nondivine living wearer and transforms that creature into a greater mummy under Osiris''s control; caster level 25; weight 3 lb.","scepter":"Unlimited-use rod of cancellation; caster level 25; weight 5 lb."},"senses":{"normalRangeMiles":18,"plantAsRemoteSenseFocus":true},"portfolioSense":"Anything affecting nature and the death of any living thing, instantaneously and eighteen weeks into past and future.","automaticActions":{"deathProducingSpellsOrDomainPowersAsFreeActions":true,"salientDivineAbilitiesExcluded":true,"freeActionDcMaximum":30,"maximumPerRound":20},"createMagicItems":"Any magic item that creates a necromantic or death effect or commands/controls plants.","avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["good","lawful"],"baseRankDamageReduction":"30/epic","sourcePrintedDamageReduction":"71/+5","increasedDamageReductionRequiresRulesEngineApplication":true,"fireResistance":23,"additionalOutsiderSkillPoints":true,"rangerHitDice":"10d8 instead of 10d10","adjustedHitPointsFromRangerHdOnly":1560,"ranger":"Apply revised ranger features appropriate to ranger level 10 rather than the book update''s 20-level example wholesale.","monk":"Apply revised monk features appropriate to monk level 12, including flurry, speed, ki strike and bonus-feat changes.","undeadQualities":"Retain the salient Undead Qualities rules independently of creature type.","defunctSkills":["Scry ranks reassigned","Wilderness Lore -> Survival/appropriate revised skills"]}}'),

('dd-statblock-ptah','Ptah Divine Stat Block','153-154',
 'Ptah is the divine-rank-15 intermediate Pharaonic creator deity of crafts, knowledge, secrets, and travel.',
 '{"deitySlug":"ptah","pantheon":"pharaonic","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"symbol":"Bull","homePlane":"Ethereal Plane","alignment":"LN","classes":[{"class":"Cleric","level":20},{"class":"Transmuter","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+200 outsider + 20d8+200 cleric + 20d4+200 transmuter","hitPoints":1000,"initiative":13,"speed":{"land":60},"armorClass":{"total":71,"dexterity":9,"divine":15,"natural":28,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"heavyMace":"+69/+64/+59/+54 melee, +5 ghost touch lawful spell storing heavy mace","heavyMaceDamage":"1d8+18/x2","spellTouch":{"melee":64,"ranged":64}},"saves":{"fort":57,"ref":56,"will":62,"intermediateDeityChecksAlways20":true},"abilities":{"str":28,"dex":29,"con":30,"int":36,"wis":40,"cha":28},"specialAttacks":{"turnUndeadPerDay":16},"specialQualities":{"printedDamageReduction":"50/+4","printedFireImmunity":true,"spellResistance":47,"divineAura":{"radiusFeet":1500,"dc":34},"familiar":"bats and owls","etherealVision":true,"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Arcane Mastery","Automatic Metamagic (quicken wizard spells)","Banishing Gaze","Clearsight","Create Greater Object","Create Object","Divine Celerity","Divine Spellcasting","Extra Domain (Law)","Extra Sense Enhancement (see ethereal)","Extra Energy Immunity (fire)","Extra Energy Immunity (sonic)","Free Move","Increased Energy Resistance (sonic)","Instant Move","Know Secrets","Power of Truth","Stride"],"uniqueAbilities":{"banishingGaze":{"rangeFeet":30,"action":"attack action","effect":"plane shift target to another plane","willSaveDc":29}},"domainPowers":{"creationSpellsCasterLevelBonus":2,"divinationSpellsCasterLevelBonus":1,"lawSpellsCasterLevelBonus":1,"freedomOfMovementRoundsPerDay":20},"spellLikeAbilities":{"casterLevel":25,"divinationAndLawCasterLevel":26,"creationCasterLevel":27,"saveDc":"34 + spell level"},"spellcasting":{"clericSpellsPerDayLevels0To15":"6/10/10/10/9/9/8/8/7/7/3/3/2/2/2/2","clericBaseDc":"27 + spell level; 31 + spell level for transmutation","wizardSpellsPerDayLevels0To13":"5/9/8/8/8/8/7/7/7/7/2/2/2/2","wizardBaseDc":"25 + spell level; 29 + spell level for transmutation","prohibitedSchools":["Enchantment","Illusion"]},"portfolioSense":"Any act of craft or creation from its beginning and fifteen weeks into the past.","automaticActions":{"skills":"Any Craft skill, even untrained","freeActionDcMaximum":25,"maximumPerRound":10},"createMagicItems":{"scope":"any magic item","maximumMarketPriceGp":200000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["lawful"],"damageReduction":"25/epic","rankBasedFireResistance":20,"fireImmunityFromSalientAbility":true,"sonicImmunityFromSalientAbility":true,"additionalOutsiderSkillPoints":true,"divineCelerity":"Functions according to revised haste.","wizardSpecialization":"Apply revised school-specialization rules.","defunctSkills":["Intuit Direction migrated","Scry ranks reassigned","Wilderness Lore -> Survival/appropriate revised skills"]}}'),

